-- Chat containers are already recorded by the source recorder (including
-- reflections). Keep delivery and retained-entry source vocabularies aligned.
ALTER TABLE assistant_delivery_sources DROP CONSTRAINT assistant_delivery_sources_source_kind_check;
ALTER TABLE assistant_delivery_sources ADD CONSTRAINT assistant_delivery_sources_source_kind_check
CHECK(source_kind IN ('task','doc','project','record','goal','routine','habit','exam','team','calendar','comment','chat','entry'));
ALTER TABLE assistant_conversation_entry_sources DROP CONSTRAINT assistant_conversation_entry_sources_source_kind_check;
ALTER TABLE assistant_conversation_entry_sources ADD CONSTRAINT assistant_conversation_entry_sources_source_kind_check
CHECK(source_kind IN ('task','doc','project','record','goal','routine','habit','exam','team','calendar','comment','chat','entry'));

-- Generated authority function; source/migration/installed parity is tested.
CREATE OR REPLACE FUNCTION assistant_source_graph_visible(p_kind text,p_id uuid,p_user uuid,p_personal boolean,p_teams uuid[])
RETURNS boolean LANGUAGE plpgsql STABLE SET jit=off AS $graph$
BEGIN
  RETURN NOT EXISTS (
    WITH RECURSIVE lineage(kind,id,personal,teams) AS (
      SELECT seed.kind,seed.id,p_personal::boolean,p_teams::uuid[] FROM (SELECT p_kind AS kind,p_id AS id) seed
      UNION
      SELECT edge.kind,edge.id,
        parent.personal AND CASE WHEN parent.kind='binding' THEN coalesce(edge_grant.personal,false) AND coalesce(edge_binding.reason<>'personal' OR edge_grant.personal,false) ELSE true END,
        CASE WHEN parent.kind='binding' THEN ARRAY(
          SELECT unnest(parent.teams) INTERSECT SELECT unnest(CASE WHEN edge_binding.reason='personal' THEN '{}'::uuid[] ELSE coalesce(edge_grant.team_ids,parent.teams) END)
          ORDER BY 1) ELSE parent.teams END
      FROM lineage parent
      LEFT JOIN assistant_delivery_bindings edge_binding ON parent.kind='binding' AND edge_binding.id=parent.id
      LEFT JOIN agent_grants edge_grant ON edge_grant.id=edge_binding.grant_id
      CROSS JOIN LATERAL (
        SELECT s.source_type AS kind,s.source_id AS id FROM memory_sources s
        WHERE parent.kind='doc' AND s.doc_id=parent.id AND s.source_id IS NOT NULL AND s.source_type IN ('task','doc','project','chat') AND NOT (s.source_type='chat' AND s.retained_entries)
        UNION SELECT 'entry',s.source_entry_id FROM memory_entry_sources s WHERE parent.kind='doc' AND s.doc_id=parent.id
        UNION SELECT s.source_kind,s.source_id FROM assistant_chat_sources s WHERE parent.kind='chat' AND s.chat_id=parent.id
        UNION SELECT 'entry',s.source_entry_id FROM assistant_turn_entry_sources s WHERE parent.kind='chat' AND s.chat_id=parent.id
        UNION SELECT 'doc',r.source_doc_id FROM work_records r WHERE parent.kind='record' AND r.id=parent.id AND r.source_doc_id IS NOT NULL
        UNION SELECT 'doc',g.plan_doc_id FROM goals g WHERE parent.kind='goal' AND g.id=parent.id AND g.plan_doc_id IS NOT NULL
        UNION SELECT 'doc',p.doc_id FROM assistant_page_bindings p WHERE parent.kind='page' AND p.id=parent.id
        UNION SELECT 'doc',c.doc_id FROM doc_comments c WHERE parent.kind='comment' AND c.id=parent.id
        UNION SELECT 'doc',unnest(e.doc_ids) FROM study_exams e WHERE parent.kind='exam' AND e.id=parent.id
        UNION SELECT s.source_kind,s.source_id FROM assistant_conversation_entry_sources s WHERE parent.kind='entry' AND s.entry_id=parent.id
        UNION SELECT 'entry',s.source_entry_id FROM assistant_conversation_entries e
          JOIN assistant_conversation_streams stream ON stream.id=e.destination_id
          JOIN assistant_turn_entry_sources s ON s.chat_id=stream.chat_id AND s.turn_id=e.turn_id WHERE parent.kind='entry' AND e.id=parent.id
        UNION SELECT 'binding',i.binding_id FROM assistant_conversation_entries e
          JOIN assistant_delivery_intents i ON i.id=e.intent_id WHERE parent.kind='entry' AND e.id=parent.id
        UNION SELECT s.source_kind,s.source_id FROM assistant_delivery_sources s WHERE parent.kind='binding' AND s.binding_id=parent.id
        UNION SELECT 'entry',s.source_entry_id FROM assistant_delivery_entry_sources s WHERE parent.kind='binding' AND s.binding_id=parent.id
        UNION SELECT s.source_kind,s.source_id FROM assistant_delivery_bindings b
          JOIN assistant_job_sources s ON b.work_kind='job' AND s.job_id=b.work_id WHERE parent.kind='binding' AND b.id=parent.id
        UNION SELECT 'entry',s.source_entry_id FROM assistant_delivery_bindings b
          JOIN ai_jobs j ON b.work_kind='job' AND j.id=b.work_id
          JOIN assistant_turn_entry_sources s ON s.chat_id=j.chat_id AND s.turn_id=j.turn_id WHERE parent.kind='binding' AND b.id=parent.id
      ) edge
    )
    SELECT 1 FROM lineage lineage_source WHERE NOT (
      CASE WHEN lineage_source.kind='entry' THEN EXISTS(SELECT 1 FROM assistant_conversation_entries lineage_entry
    JOIN assistant_conversation_streams lineage_stream ON lineage_stream.id=lineage_entry.destination_id
    JOIN ai_chats lineage_chat ON lineage_chat.id=lineage_stream.chat_id
    JOIN users lineage_owner ON lineage_owner.id=lineage_stream.owner_id
    WHERE lineage_entry.id=lineage_source.id AND lineage_entry.sources_checked AND lineage_stream.owner_id=p_user
      AND NOT lineage_owner.disabled AND lineage_stream.retired_at IS NULL AND lineage_chat.swept_at IS NULL
      AND (lineage_chat.user_id = p_user AND (lineage_source.personal OR lineage_chat.project_id IS NOT NULL OR lineage_chat.scope_kind='task')
    AND NOT EXISTS(SELECT 1 FROM assistant_conversation_streams retired_source WHERE retired_source.chat_id=lineage_chat.id AND retired_source.retired_at IS NOT NULL)
    AND (lineage_chat.project_id IS NULL OR EXISTS(SELECT 1 FROM projects visible_project
      WHERE visible_project.id = lineage_chat.project_id AND (((visible_project.team_id IS NULL AND visible_project.user_id = p_user AND lineage_source.personal::boolean) OR (visible_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_project.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT visible_project.assistant_off)))
    AND (lineage_chat.scope_kind IS DISTINCT FROM 'task' OR EXISTS(SELECT 1 FROM items visible_task
      WHERE visible_task.id = lineage_chat.scope_id AND (((visible_task.team_id IS NULL AND visible_task.user_id = p_user AND lineage_source.personal::boolean) OR (visible_task.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_task.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = visible_task.project_id AND ko.assistant_off))))))
      WHEN lineage_source.kind='binding' THEN EXISTS(
        SELECT 1 FROM assistant_delivery_bindings lineage_binding WHERE lineage_binding.id=lineage_source.id
        AND (lineage_binding.owner_id=p_user AND lineage_binding.sources_checked AND EXISTS(
    SELECT 1 FROM agent_grants delivery_grant JOIN users delivery_owner ON delivery_owner.id=delivery_grant.user_id
    WHERE delivery_grant.id=lineage_binding.grant_id AND delivery_grant.user_id=p_user
      AND NOT delivery_owner.disabled AND delivery_grant.revoked_at IS NULL AND delivery_grant.suspended_at IS NULL
      AND (delivery_grant.expires_at IS NULL OR delivery_grant.expires_at>now())
      AND NOT EXISTS(SELECT 1 FROM assistant_delivery_sources ds WHERE ds.binding_id=lineage_binding.id
        AND NOT (CASE ds.source_kind
    WHEN 'entry' THEN EXISTS(SELECT 1 FROM assistant_conversation_entries lineage_entry
    JOIN assistant_conversation_streams lineage_stream ON lineage_stream.id=lineage_entry.destination_id
    JOIN ai_chats lineage_chat ON lineage_chat.id=lineage_stream.chat_id
    JOIN users lineage_owner ON lineage_owner.id=lineage_stream.owner_id
    WHERE lineage_entry.id=ds.source_id AND lineage_entry.sources_checked AND lineage_stream.owner_id=p_user
      AND NOT lineage_owner.disabled AND lineage_stream.retired_at IS NULL AND lineage_chat.swept_at IS NULL
      AND (lineage_chat.user_id = p_user AND (delivery_grant.personal OR lineage_chat.project_id IS NOT NULL OR lineage_chat.scope_kind='task')
    AND NOT EXISTS(SELECT 1 FROM assistant_conversation_streams retired_source WHERE retired_source.chat_id=lineage_chat.id AND retired_source.retired_at IS NOT NULL)
    AND (lineage_chat.project_id IS NULL OR EXISTS(SELECT 1 FROM projects visible_project
      WHERE visible_project.id = lineage_chat.project_id AND (((visible_project.team_id IS NULL AND visible_project.user_id = p_user AND delivery_grant.personal::boolean) OR (visible_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_project.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT visible_project.assistant_off)))
    AND (lineage_chat.scope_kind IS DISTINCT FROM 'task' OR EXISTS(SELECT 1 FROM items visible_task
      WHERE visible_task.id = lineage_chat.scope_id AND (((visible_task.team_id IS NULL AND visible_task.user_id = p_user AND delivery_grant.personal::boolean) OR (visible_task.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_task.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = visible_task.project_id AND ko.assistant_off))))))
    WHEN 'page' THEN EXISTS(SELECT 1 FROM assistant_page_bindings source_binding JOIN docs source_doc ON source_doc.id=source_binding.doc_id WHERE source_binding.id=ds.source_id AND source_binding.user_id=p_user AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND delivery_grant.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))
    WHEN 'doc' THEN EXISTS(SELECT 1 FROM docs source_doc WHERE source_doc.id=ds.source_id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND delivery_grant.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))
    WHEN 'project' THEN EXISTS(SELECT 1 FROM projects source_project WHERE source_project.id=ds.source_id AND (((source_project.team_id IS NULL AND source_project.user_id = p_user AND delivery_grant.personal::boolean) OR (source_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_project.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT source_project.assistant_off))
    WHEN 'team' THEN EXISTS(SELECT 1 FROM team_members source_member WHERE source_member.team_id=ds.source_id AND source_member.user_id=p_user AND source_member.team_id=ANY(coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))
    WHEN 'calendar' THEN EXISTS(SELECT 1 FROM calendar_subscriptions source_calendar WHERE source_calendar.id=ds.source_id AND source_calendar.user_id=p_user AND delivery_grant.personal)
    WHEN 'task' THEN EXISTS(SELECT 1 FROM items source_item WHERE source_item.id=ds.source_id AND (((source_item.team_id IS NULL AND source_item.user_id = p_user AND delivery_grant.personal::boolean) OR (source_item.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_item.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_item.project_id AND ko.assistant_off)))
    WHEN 'record' THEN EXISTS(SELECT 1 FROM work_records source_record WHERE source_record.id=ds.source_id AND (((source_record.team_id IS NULL AND source_record.created_by = p_user AND delivery_grant.personal::boolean) OR (source_record.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_record.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_record.project_id AND ko.assistant_off))
      AND (source_record.source_doc_id IS NULL OR EXISTS(SELECT 1 FROM docs source_doc WHERE source_doc.id=source_record.source_doc_id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND delivery_grant.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))))
    WHEN 'routine' THEN EXISTS(SELECT 1 FROM agent_routines source_routine WHERE source_routine.id=ds.source_id AND source_routine.user_id=p_user AND delivery_grant.personal)
    WHEN 'habit' THEN EXISTS(SELECT 1 FROM habits source_habit WHERE source_habit.id=ds.source_id AND source_habit.user_id=p_user AND delivery_grant.personal)
    WHEN 'goal' THEN EXISTS(SELECT 1 FROM goals source_goal WHERE source_goal.id=ds.source_id AND source_goal.user_id=p_user AND delivery_grant.personal
      AND (source_goal.project_id IS NULL OR EXISTS(SELECT 1 FROM projects source_project WHERE source_project.id=source_goal.project_id AND (((source_project.team_id IS NULL AND source_project.user_id = p_user AND delivery_grant.personal::boolean) OR (source_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_project.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT source_project.assistant_off)))
      AND (source_goal.plan_doc_id IS NULL OR EXISTS(SELECT 1 FROM docs source_doc WHERE source_doc.id=source_goal.plan_doc_id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND delivery_grant.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))))
    WHEN 'comment' THEN EXISTS(SELECT 1 FROM doc_comments source_comment JOIN docs source_doc ON source_doc.id=source_comment.doc_id WHERE source_comment.id=ds.source_id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND delivery_grant.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))
    WHEN 'exam' THEN EXISTS(SELECT 1 FROM study_exams source_exam WHERE source_exam.id=ds.source_id AND source_exam.user_id=p_user AND delivery_grant.personal
      AND NOT EXISTS(SELECT 1 FROM unnest(source_exam.doc_ids) source_doc_id LEFT JOIN docs source_doc ON source_doc.id=source_doc_id WHERE source_doc.id IS NULL OR NOT (((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND delivery_grant.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off))))
      AND (source_exam.own OR coalesce(source_exam.source_ref,source_exam.exam_key) NOT LIKE 'sub:%' OR EXISTS(SELECT 1 FROM calendar_subscriptions source_calendar JOIN external_events source_event ON source_event.subscription_id=source_calendar.id WHERE source_calendar.user_id=p_user AND delivery_grant.personal AND source_calendar.id::text=split_part(coalesce(source_exam.source_ref,source_exam.exam_key), ':', 2) AND md5(source_event.uid)=split_part(split_part(coalesce(source_exam.source_ref,source_exam.exam_key), ':', 3), '|', 1)))
      AND (source_exam.exam_key NOT LIKE 'item:%' OR EXISTS(SELECT 1 FROM items source_item WHERE source_item.id::text=split_part(split_part(source_exam.exam_key, ':', 2), '|', 1) AND (((source_item.team_id IS NULL AND source_item.user_id = p_user AND delivery_grant.personal::boolean) OR (source_item.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_item.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_item.project_id AND ko.assistant_off)))))

    WHEN 'chat' THEN EXISTS(SELECT 1 FROM ai_chats source_chat WHERE source_chat.id=ds.source_id AND (source_chat.user_id = p_user AND (delivery_grant.personal OR source_chat.project_id IS NOT NULL OR source_chat.scope_kind='task')
    AND NOT EXISTS(SELECT 1 FROM assistant_conversation_streams retired_source WHERE retired_source.chat_id=source_chat.id AND retired_source.retired_at IS NOT NULL)
    AND (source_chat.project_id IS NULL OR EXISTS(SELECT 1 FROM projects visible_project
      WHERE visible_project.id = source_chat.project_id AND (((visible_project.team_id IS NULL AND visible_project.user_id = p_user AND delivery_grant.personal::boolean) OR (visible_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_project.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT visible_project.assistant_off)))
    AND (source_chat.scope_kind IS DISTINCT FROM 'task' OR EXISTS(SELECT 1 FROM items visible_task
      WHERE visible_task.id = source_chat.scope_id AND (((visible_task.team_id IS NULL AND visible_task.user_id = p_user AND delivery_grant.personal::boolean) OR (visible_task.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_task.team_id = ANY (coalesce(delivery_grant.team_ids,ARRAY(SELECT team_id FROM team_members WHERE user_id=p_user))::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = visible_task.project_id AND ko.assistant_off))))))
    ELSE false END))
      AND (lineage_binding.reason<>'personal' OR (delivery_grant.personal AND NOT EXISTS(
        SELECT 1 FROM assistant_delivery_sources ds WHERE ds.binding_id=lineage_binding.id AND NOT
        (CASE ds.source_kind
    WHEN 'entry' THEN EXISTS(SELECT 1 FROM assistant_conversation_entries lineage_entry
    JOIN assistant_conversation_streams lineage_stream ON lineage_stream.id=lineage_entry.destination_id
    JOIN ai_chats lineage_chat ON lineage_chat.id=lineage_stream.chat_id
    JOIN users lineage_owner ON lineage_owner.id=lineage_stream.owner_id
    WHERE lineage_entry.id=ds.source_id AND lineage_entry.sources_checked AND lineage_stream.owner_id=p_user
      AND NOT lineage_owner.disabled AND lineage_stream.retired_at IS NULL AND lineage_chat.swept_at IS NULL
      AND (lineage_chat.user_id = p_user AND (true OR lineage_chat.project_id IS NOT NULL OR lineage_chat.scope_kind='task')
    AND NOT EXISTS(SELECT 1 FROM assistant_conversation_streams retired_source WHERE retired_source.chat_id=lineage_chat.id AND retired_source.retired_at IS NOT NULL)
    AND (lineage_chat.project_id IS NULL OR EXISTS(SELECT 1 FROM projects visible_project
      WHERE visible_project.id = lineage_chat.project_id AND (((visible_project.team_id IS NULL AND visible_project.user_id = p_user) OR (visible_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_project.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT visible_project.assistant_off)))
    AND (lineage_chat.scope_kind IS DISTINCT FROM 'task' OR EXISTS(SELECT 1 FROM items visible_task
      WHERE visible_task.id = lineage_chat.scope_id AND (((visible_task.team_id IS NULL AND visible_task.user_id = p_user) OR (visible_task.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_task.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = visible_task.project_id AND ko.assistant_off))))))
    WHEN 'page' THEN EXISTS(SELECT 1 FROM assistant_page_bindings source_binding JOIN docs source_doc ON source_doc.id=source_binding.doc_id WHERE source_binding.id=ds.source_id AND source_binding.user_id=p_user AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))
    WHEN 'doc' THEN EXISTS(SELECT 1 FROM docs source_doc WHERE source_doc.id=ds.source_id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))
    WHEN 'project' THEN EXISTS(SELECT 1 FROM projects source_project WHERE source_project.id=ds.source_id AND (((source_project.team_id IS NULL AND source_project.user_id = p_user) OR (source_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_project.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT source_project.assistant_off))
    WHEN 'team' THEN EXISTS(SELECT 1 FROM team_members source_member WHERE source_member.team_id=ds.source_id AND source_member.user_id=p_user AND source_member.team_id=ANY('{}'::uuid[]::uuid[]))
    WHEN 'calendar' THEN EXISTS(SELECT 1 FROM calendar_subscriptions source_calendar WHERE source_calendar.id=ds.source_id AND source_calendar.user_id=p_user AND true)
    WHEN 'task' THEN EXISTS(SELECT 1 FROM items source_item WHERE source_item.id=ds.source_id AND (((source_item.team_id IS NULL AND source_item.user_id = p_user) OR (source_item.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_item.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_item.project_id AND ko.assistant_off)))
    WHEN 'record' THEN EXISTS(SELECT 1 FROM work_records source_record WHERE source_record.id=ds.source_id AND (((source_record.team_id IS NULL AND source_record.created_by = p_user) OR (source_record.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_record.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_record.project_id AND ko.assistant_off))
      AND (source_record.source_doc_id IS NULL OR EXISTS(SELECT 1 FROM docs source_doc WHERE source_doc.id=source_record.source_doc_id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))))
    WHEN 'routine' THEN EXISTS(SELECT 1 FROM agent_routines source_routine WHERE source_routine.id=ds.source_id AND source_routine.user_id=p_user AND true)
    WHEN 'habit' THEN EXISTS(SELECT 1 FROM habits source_habit WHERE source_habit.id=ds.source_id AND source_habit.user_id=p_user AND true)
    WHEN 'goal' THEN EXISTS(SELECT 1 FROM goals source_goal WHERE source_goal.id=ds.source_id AND source_goal.user_id=p_user AND true
      AND (source_goal.project_id IS NULL OR EXISTS(SELECT 1 FROM projects source_project WHERE source_project.id=source_goal.project_id AND (((source_project.team_id IS NULL AND source_project.user_id = p_user) OR (source_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_project.team_id = ANY ('{}'::uuid[]::uuid[]))) AND NOT source_project.assistant_off)))
