    WHEN 'goal' THEN EXISTS(SELECT 1 FROM goals source_goal WHERE source_goal.id=lineage_source.id AND source_goal.user_id=p_user AND lineage_source.personal
      AND (source_goal.project_id IS NULL OR EXISTS(SELECT 1 FROM projects source_project WHERE source_project.id=source_goal.project_id AND (((source_project.team_id IS NULL AND source_project.user_id = p_user AND lineage_source.personal::boolean) OR (source_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_project.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT source_project.assistant_off)))
      AND (source_goal.plan_doc_id IS NULL OR EXISTS(SELECT 1 FROM docs source_doc WHERE source_doc.id=source_goal.plan_doc_id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND lineage_source.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))))
    WHEN 'comment' THEN EXISTS(SELECT 1 FROM doc_comments source_comment JOIN docs source_doc ON source_doc.id=source_comment.doc_id WHERE source_comment.id=lineage_source.id AND ((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND lineage_source.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)))
    WHEN 'exam' THEN EXISTS(SELECT 1 FROM study_exams source_exam WHERE source_exam.id=lineage_source.id AND source_exam.user_id=p_user AND lineage_source.personal
      AND NOT EXISTS(SELECT 1 FROM unnest(source_exam.doc_ids) source_doc_id LEFT JOIN docs source_doc ON source_doc.id=source_doc_id WHERE source_doc.id IS NULL OR NOT (((((source_doc.team_id IS NULL AND source_doc.user_id = p_user AND lineage_source.personal::boolean) OR (source_doc.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_doc.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off)) AND source_doc.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_doc.project_id AND ko.assistant_off))))
      AND (source_exam.own OR coalesce(source_exam.source_ref,source_exam.exam_key) NOT LIKE 'sub:%' OR EXISTS(SELECT 1 FROM calendar_subscriptions source_calendar JOIN external_events source_event ON source_event.subscription_id=source_calendar.id WHERE source_calendar.user_id=p_user AND lineage_source.personal AND source_calendar.id::text=split_part(coalesce(source_exam.source_ref,source_exam.exam_key), ':', 2) AND md5(source_event.uid)=split_part(split_part(coalesce(source_exam.source_ref,source_exam.exam_key), ':', 3), '|', 1)))
      AND (source_exam.exam_key NOT LIKE 'item:%' OR EXISTS(SELECT 1 FROM items source_item WHERE source_item.id::text=split_part(split_part(source_exam.exam_key, ':', 2), '|', 1) AND (((source_item.team_id IS NULL AND source_item.user_id = p_user AND lineage_source.personal::boolean) OR (source_item.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND source_item.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = source_item.project_id AND ko.assistant_off)))))

    WHEN 'chat' THEN EXISTS(SELECT 1 FROM ai_chats source_chat WHERE source_chat.id=lineage_source.id AND (source_chat.user_id = p_user AND (lineage_source.personal OR source_chat.project_id IS NOT NULL OR source_chat.scope_kind='task')
    AND NOT EXISTS(SELECT 1 FROM assistant_conversation_streams retired_source WHERE retired_source.chat_id=source_chat.id AND retired_source.retired_at IS NOT NULL)
    AND (source_chat.project_id IS NULL OR EXISTS(SELECT 1 FROM projects visible_project
      WHERE visible_project.id = source_chat.project_id AND (((visible_project.team_id IS NULL AND visible_project.user_id = p_user AND lineage_source.personal::boolean) OR (visible_project.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_project.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT visible_project.assistant_off)))
    AND (source_chat.scope_kind IS DISTINCT FROM 'task' OR EXISTS(SELECT 1 FROM items visible_task
      WHERE visible_task.id = source_chat.scope_id AND (((visible_task.team_id IS NULL AND visible_task.user_id = p_user AND lineage_source.personal::boolean) OR (visible_task.team_id IN (SELECT team_id FROM team_members WHERE user_id = p_user) AND visible_task.team_id = ANY (lineage_source.teams::uuid[]))) AND NOT EXISTS (SELECT 1 FROM projects ko WHERE ko.id = visible_task.project_id AND ko.assistant_off))))))
    ELSE false END)
      END
      AND (lineage_source.kind<>'chat' OR EXISTS(
        SELECT 1 FROM ai_chats memory_chat WHERE memory_chat.id=lineage_source.id
        AND (memory_chat.origin='person' OR EXISTS(SELECT 1 FROM assistant_chat_sources recorded WHERE recorded.chat_id=memory_chat.id))
      ))
    ));
END;
$graph$;
